// 新首任本人到柜台显式接任，保持原Office、原Role定义与所有旧文书主体，不制造远程代办。
#include "political_office_reception_detail.hpp"
namespace hanmo::resident {namespace {
// 原请求每个权源字段都冻结，原报价不能被改为另一Office或旧角色来源。
bool same(const PoliticalAssumeOfficeReception& a,const PoliticalAssumeOfficeReception& b){return std::tie(a.authority.organization_id,a.authority.office_id,a.authority.authority_epoch,a.authority.actor_id,a.policy_id,a.expected_role_actor_id,a.expected_assignment_fact_id)==std::tie(b.authority.organization_id,b.authority.office_id,b.authority.authority_epoch,b.authority.actor_id,b.policy_id,b.expected_role_actor_id,b.expected_assignment_fact_id);}
}
Outcome<PoliticalOfficeReceptionQuote> preview_political_office_reception(const PoliticalOfficeReceptionContext& x,const StableId& actor,const PoliticalAssumeOfficeReception& command){
 auto fail=[](const Status& v){return Outcome<PoliticalOfficeReceptionQuote>{false,{},v.error};};if(actor!=x.common.state().metadata.player_actor_id)return fail(common_failure("PoliticalOfficeReceptionPlayerRequired"));auto valid=validate_political_office_reception_sources(x);if(!valid.ok)return fail(valid);if(x.state.assignments.size()>=4096)return fail(common_failure("PoliticalOfficeReceptionHistoryCapacity"));const auto* p=x.catalog.policies.find(command.policy_id);const auto* original=p?x.successions.policies.find(p->succession_policy_id):nullptr;if(!p||!original)return fail(common_failure("PoliticalOfficeReceptionPolicyRequired"));const auto& authority=command.authority;if(authority.actor_id!=actor||authority.organization_id!=original->organization_id||authority.office_id!=original->leader_office_id)return fail(common_failure("PoliticalOfficeReceptionOriginalOfficeRequired"));
 auto current=read_political_office_reception(x.common,x.common_catalog,x.successions,x.catalog,x.state,p->id);if(!current.ok)return {false,{},current.error};if(current.value.actor_id!=command.expected_role_actor_id||current.value.assignment_fact_id!=command.expected_assignment_fact_id)return fail(common_failure("PoliticalOfficeReceptionRoleVersionChanged"));if(current.value.actor_id==actor)return fail(common_failure("PoliticalOfficeReceptionAlreadyHeld"));
 auto office=read_political_succession_office(x.common,x.organizations,x.organization_catalog,*original);if(!office.ok)return {false,{},office.error};const auto* active=x.organizations.offices.find(original->leader_office_id);if(office.value.vacant||office.value.holder_actor_id!=std::optional<StableId>{actor}||office.value.office_epoch!=authority.authority_epoch||!active||active->deputy_actor_id)return fail(common_failure("PoliticalOfficeReceptionCurrentOfficeRequired"));
 valid=politics_detail::available(x.common,x.activity,actor);if(!valid.ok)return fail(valid);const auto* person=x.common.actor(actor);const auto* place=person?std::get_if<SettlementLocation>(&person->location):nullptr;if(!place||place->place_id!=original->seat_place_id)return fail(common_failure("PoliticalOfficeReceptionSeatRequired"));if(x.activity.in_interaction(actor)||x.activity.in_interaction(current.value.actor_id)||x.activity.has_existing_contract_service(current.value.actor_id,p->role_id))return fail(common_failure("PoliticalOfficeReceptionCounterBusy"));valid=growth_independent_office_age(x.common,actor);if(!valid.ok)return fail(valid);OrganizationAccess members(x.common,x.organizations,x.organization_catalog,x.economy);if(!members.actor_accepts_duty(actor,original->organization_id))return fail(common_failure("PoliticalOfficeReceptionMemberUnavailable"));
 auto proof=check_authority(x.common,x.organizations,x.organization_catalog,authority,political_office_reception_command,{ScopeRef::Kind::site,original->seat_place_id},0);if(!proof.ok)return {false,{},proof.error};valid=office_reception_detail::grant(x,*p,x.common.tick());if(!valid.ok)return fail(valid);valid=x.seat(*original,x.common.tick(),{});if(!valid.ok)return fail(valid);return {true,{x.common.state().identity,actor,command},{}};
}
// 先完整重报价再写唯一Role；外层原Common保存点覆盖角色、计数和新事实的全部失败。
Outcome<StableId> apply_political_office_reception_in_candidate(CommonStore& common,PoliticalOfficeReceptionState& state,const PoliticalOfficeReceptionContext& x,const StableId& actor,const PoliticalAssumeOfficeReception& command,const PoliticalOfficeReceptionQuote& quote){
 const auto& a=common.state().identity;const auto& b=quote.identity;if(&common!=&x.common||&state!=&x.state||quote.actor_id!=actor||!same(command,quote.command)||std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick))return {false,{},common_failure("StalePoliticalOfficeReceptionQuote").error};auto fresh=preview_political_office_reception(x,actor,command);if(!fresh.ok)return {false,{},fresh.error};const auto& p=*x.catalog.policies.find(command.policy_id);const auto& original=*x.successions.policies.find(p.succession_policy_id);auto office=read_political_succession_office(common,x.organizations,x.organization_catalog,original);if(!office.ok)return {false,{},office.error};
 auto next=state;auto id=common.next_id("political_office_reception");if(!id.ok)return id;PoliticalOfficeReceptionAssignment row;row.id=id.value;row.policy_id=p.id;row.organization_id=original.organization_id;row.office_id=original.leader_office_id;row.role_id=p.role_id;row.actor_id=actor;row.previous_actor_id=command.expected_role_actor_id;row.previous_assignment_fact_id=command.expected_assignment_fact_id;row.office_change_fact_id=office.value.latest_office_fact_id;row.grant_id=p.reception_grant_id;row.office_epoch=command.authority.authority_epoch;row.tick=common.tick();if(!next.assignments.insert(row.id,row))return {false,{},common_failure("DuplicatePoliticalOfficeReceptionSource").error};auto role=*common.state().roles.find(p.role_id);role.actor_id=actor;role.enabled=true;auto valid=common.apply_role(p.role_id,role);if(!valid.ok)return {false,{},valid.error};valid=common.append_fact({id.value,"political_office_reception_assumed",political_office_reception_domain});if(!valid.ok)return {false,{},valid.error};state=std::move(next);return id;
}
}
